import{_ as n,o as s,c as o,ah as t}from"./chunks/framework.C-FRNfAJ.js";const g=JSON.parse('{"title":"Communication","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/coordinateur/communication.md","filePath":"src/guide/coordinateur/communication.md"}'),r={name:"guide/coordinateur/communication.md"};function a(i,e,u,c,l,p){return s(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h1><p><strong>Formation → Communication</strong> comporte deux rubriques : <strong>Annonces</strong> et <strong>Envois</strong>. Le Coordinateur pédagogique et l&#39;Administrateur y ont accès. Les échanges de tous les jours entre apprenants et formateurs restent dans Sève.</p><h2 id="envoyer-une-annonce" tabindex="-1">Envoyer une annonce <a class="header-anchor" href="#envoyer-une-annonce" aria-label="Permalink to &quot;Envoyer une annonce&quot;">​</a></h2><p><strong>Nouvelle annonce</strong> :</p><ol><li>Choisissez les <strong>destinataires</strong> : <strong>Une cohorte</strong> (en cours ou à venir) ou <strong>Un référentiel</strong>, ce qui vise toutes ses cohortes en cours ou à venir.</li><li>Cochez ou décochez <strong>Inclure les formateurs et coachs-tuteurs affectés</strong>, coché par défaut.</li><li>Saisissez l&#39;<strong>objet</strong> et le <strong>message</strong> (séparez les paragraphes par une ligne vide).</li><li><strong>Envoyer l&#39;annonce</strong>.</li></ol><p>L&#39;envoi est <strong>immédiat</strong>, par e-mail, et sur Sève pour les comptes qui y sont ouverts. Il n&#39;y a <strong>pas de WhatsApp</strong> pour les annonces.</p><p>Les destinataires sont les apprenants dont l&#39;inscription est en attente de signature, active ou suspendue. Chacun n&#39;est servi <strong>qu&#39;une fois</strong>, même s&#39;il est dans plusieurs cohortes visées ; une annonce <strong>sans destinataire est refusée</strong>.</p><p>La liste <strong>Annonces envoyées</strong> garde, pour chacune, son auteur, son nombre de destinataires, ses e-mails, ses envois sur Sève et ses échecs.</p><h2 id="le-journal-des-envois" tabindex="-1">Le journal des envois <a class="header-anchor" href="#le-journal-des-envois" aria-label="Permalink to &quot;Le journal des envois&quot;">​</a></h2><p><strong>Envois</strong> montre <strong>tout ce que le moteur de notifications a envoyé</strong> : rappels, avis et annonces, canal par canal, avec le destinataire, le message, la date, le statut (<strong>Envoyé</strong> ou <strong>Échec</strong>) et l&#39;erreur éventuelle.</p><p>Filtrez par canal et par statut, cherchez un destinataire ou un objet, et utilisez <strong>Voir les échecs</strong> pour retrouver ce qui n&#39;a pas abouti, avec le nombre d&#39;échecs des 30 derniers jours. Un canal en échec n&#39;empêche pas les autres : un message qui n&#39;a pas pu partir sur Sève est parti par e-mail.</p>',11)])])}const m=n(r,[["render",a]]);export{g as __pageData,m as default};
